INSERT IGNORE INTO whatsapp_group_member_fact (
  group_link_id, group_jid, member_jid, participant_jid, phone,
  role, is_admin, is_owner, membership_status, status_source,
  occurred_at, source_event_id, observer_account_id, created_at
) VALUES (
  #{groupLinkId}, #{groupJid}, #{memberJid}, #{participantJid}, #{phone},
  #{role}, #{admin}, #{owner}, #{membershipStatus}, #{statusSource},
  #{statusUpdatedAt}, #{statusSourceEventId}, #{observerAccountId}, #{createdAt}
)

